<template><view class="page"><view class="card"><text class="heading">生产报表</text><text class="muted">生成范围：{{farmName}}；历史归档覆盖当前经营主体。</text><view class="buttons"><button size="mini" @click="tab='reports';load()">报表归档</button><button size="mini" @click="tab='subscriptions';load()">历史通知</button><button size="mini" :disabled="busy" @click="creating=!creating">生成报表</button></view><view v-if="creating"><business-fields :fields="fields" v-model="form" :disabled="busy"/><button :disabled="busy" :loading="busy" class="primary" @click="generate">生成并核验</button></view><view v-if="tab==='reports'"><business-fields :fields="filtersFields" v-model="filters"/><button size="mini" :disabled="busy" @click="load()">查询</button></view><text v-else class="muted">自动通知尚未接入；这里只查看、取消历史配置。</text></view><view v-if="error" class="error">{{error}}</view><text class="muted">{{busy?'正在处理…':`共 ${total} 条`}}</text><view v-for="r in rows" :key="r.reportId || r.subscribeId" class="card"><template v-if="tab==='reports'"><text class="heading">{{r.reportName}}</text><text class="muted">{{typeLabel(r.reportType)}} · {{r.period}}</text><text class="muted">{{r.generatedAt}} · {{r.generatorName || '未记录生成人'}}</text><text>{{r.status===2?'已生成':r.status===3?'生成失败':'生成中'}}</text><view class="buttons"><button size="mini" :disabled="busy||r.status!==2" @click="download(r)">下载 CSV</button><button size="mini" :disabled="busy" @click="remove(r)">删除报表</button></view></template><template v-else><text class="heading">{{typeLabel(r.reportType)}} · {{r.period}}</text><text class="muted">{{(r.receivers||[]).join('、')}}</text><button size="mini" :disabled="busy" @click="remove(r)">取消历史配置</button></template></view><view v-if="!busy&&!error&&!rows.length" class="card muted">暂无记录</view><button v-if="rows.length<total" :disabled="busy" @click="load(true)">加载更多</button></view></template>
<script setup lang="ts">
import {ref} from 'vue'
import {onShow,onHide,onPullDownRefresh} from '@dcloudio/uni-app'
import {call,date,select,text,type Row} from '@/api/native-business'
import {normalizePage} from '@/utils/request'
import {contextGuard,downloadReport} from '@/utils/business-files'
import {ensureWorkspaceSession,isProductionOps} from '@/utils/workspace'
import {resolveCurrentFarm} from '@/utils/auth-helper'
import BusinessFields from '@/components/business-fields/business-fields.vue'
const types=['日报','周报','月报','季报','年报'].map((label,i)=>({label,value:i+1})),typeLabel=(v:any)=>types.find(t=>t.value===v)?.label||'报表'
const fields=[select('reportType','报表周期',types,true),date('period','周期内任意一天',true)],filtersFields=[select('reportType','报表类型',types),text('period','报表名称或周期')]
const rows=ref<Row[]>([]),total=ref(0),tab=ref('reports'),creating=ref(false),form=ref<Row>({reportType:3,period:''}),filters=ref<Row>({}),farmId=ref(''),farmName=ref(''),busy=ref(false),error=ref('');let page=1,version=0
async function load(more=false){const run=++version;error.value='';busy.value=true;try{if(!await ensureWorkspaceSession())return;if(isProductionOps())throw new Error('请切换到用户端');const farm=await resolveCurrentFarm();if(!farm)return;farmId.value=String(farm.farmId);farmName.value=farm.farmName||'';const guard=contextGuard(),next=more?page+1:1;const raw=await call('/analytics/reports'+(tab.value==='subscriptions'?'/subscriptions':''),'GET',undefined,{...filters.value,pageNum:next,pageSize:20});guard();if(run!==version)return;const data=normalizePage<Row>(raw,next,20);rows.value=more?rows.value.concat(data.list):data.list;total.value=data.total;page=next}catch(e:any){if(run===version){rows.value=[];error.value=e.message}}finally{if(run===version)busy.value=false;uni.stopPullDownRefresh()}}
async function generate(){if(busy.value)return;error.value='';let written=false;try{if(!form.value.period)throw new Error('请选择周期内日期');const guard=contextGuard();busy.value=true;const result=await call('/analytics/reports','POST',{...form.value,farmId:farmId.value});written=true;guard();const raw=await call('/analytics/reports','GET',undefined,{period:result.period,pageNum:1,pageSize:100});guard();if(!normalizePage<Row>(raw,1,100).list.some(r=>String(r.reportId)===String(result.reportId)))throw new Error('列表尚未找到新报表，请刷新核对，勿重复生成');creating.value=false;filters.value={period:result.period};tab.value='reports';await load();uni.showToast({title:'已生成并核验',icon:'success'})}catch(e:any){error.value=(written?'已生成，回读提示：':'')+e.message}finally{busy.value=false}}
async function download(r:Row){if(busy.value)return;busy.value=true;error.value='';try{await downloadReport(String(r.reportId))}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function remove(r:Row){if(busy.value)return;const kind=tab.value;const guard=contextGuard();const yes=await new Promise<boolean>(resolve=>uni.showModal({title:kind==='reports'?'删除报表？':'取消历史通知？',content:'仅操作所选记录，请确认。',success:r=>resolve(r.confirm),fail:()=>resolve(false)}));if(!yes)return;busy.value=true;try{guard();const result=await call('/analytics/reports/'+(kind==='subscriptions'?'subscriptions/':'')+encodeURIComponent(r.reportId||r.subscribeId),'DELETE');guard();if(result!==true)throw new Error('服务端未确认操作成功');await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
onShow(()=>void load());onHide(()=>{version++;rows.value=[];creating.value=false});onPullDownRefresh(()=>void load())
</script>
<style scoped>.page{padding:24rpx 24rpx calc(40rpx + env(safe-area-inset-bottom));min-height:100vh;background:#f4f6f2;box-sizing:border-box}.card{padding:28rpx;margin-bottom:24rpx;border-radius:18rpx;background:white;font-size:28rpx}.heading{display:block;font-size:32rpx;font-weight:600;margin-bottom:18rpx}.muted{display:block;font-size:24rpx;color:#666666;line-height:1.8;margin:12rpx 0}.buttons{display:flex;flex-wrap:wrap;gap:16rpx;margin-top:22rpx}.buttons button{margin:0;min-height:84rpx;font-size:25rpx}.primary{background:#126d43;color:white;font-size:28rpx}.error{padding:24rpx;margin-bottom:24rpx;background:#fff0e8;color:#a43e28;font-size:26rpx}</style>
